import * as React from 'react'

import {useIsSakuraSelected} from '../../../../../hooks/useIsSakuraSelected'
import useMyId from '../../../../../hooks/useMyId'
import {getIsSakuraUI} from '../../../../../selectors'
import {GUEST_ID} from '../../../../../types'
import type {LinkType} from '../../Header.consts'

import type {LinkTarget, Props} from './LinkHost'
import LinkHost from './LinkHost'

import {useAppSelector} from 'src/hooks/react-redux'

type OwnProps = Omit<Props, 'link' | 'isSakuraUI'> & {
  to?: LinkType
}
const temporaryClassicUISessionKey = 'isTemporaryClassicUISession'

function LinkHostContainer({to, ...props}: OwnProps) {
  const userId = useMyId()
  const isSakuraSelected = useIsSakuraSelected()
  const isSakuraUI = useAppSelector(getIsSakuraUI)
  const isGuest = userId === GUEST_ID
  const link: LinkTarget | null = React.useMemo(() => {
    if (to == null) {
      return null
    }
    if (to.sakura == null) {
      return {
        to: to.classic,
        sakura: false,
      }
    }

    const isTemporaryClassicUISession =
      window.sessionStorage.getItem(temporaryClassicUISessionKey) === 'true'

    if (isGuest) {
      if (isTemporaryClassicUISession) {
        return {
          to: to.classic,
          sakura: false,
        }
      }

      if (isSakuraUI) {
        return {
          to: to.sakura,
          sakura: true,
        }
      }
    }

    return {
      to: isSakuraSelected && !isTemporaryClassicUISession ? to.sakura : to.classic,
      sakura: isSakuraSelected,
    }
  }, [isSakuraUI, isGuest, isSakuraSelected, to])

  if (link != null && link.to == null) {
    return null
  }

  return <LinkHost link={link} isSakuraUI={isSakuraUI} {...props} />
}

export default React.memo(LinkHostContainer)
