import * as React from 'react'

import {headerAdministrationLinkHint} from '../../../../packages/Hints/HintItems/Hints.navigation'
import {useHint} from '../../../../packages/Hints/Hints.hooks'
import {LINKS} from '../../Header.consts'
import HeaderLinkHost from '../LinkHost/LinkHost.container'
import {isActiveClassicUILink} from '../Links.utils'

function AdministrationLink() {
  useHint(headerAdministrationLinkHint)
  const isActive =
    document.location.pathname.includes('/admin/') && !isActiveClassicUILink('projects')

  return (
    <HeaderLinkHost
      data-hint-container-id={headerAdministrationLinkHint.id}
      title={'Administration'}
      to={LINKS.administration}
      active={isActive}
      icon="settings-20px"
    >
      {'Admin'}
    </HeaderLinkHost>
  )
}

export default React.memo(AdministrationLink)
