import Link, {type LinkProps} from '@jetbrains/ring-ui-built/components/link/link'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {ReactNode} from 'react'
import {useId} from 'react'

import RouterLink from '../../../../../containers/EntityLink'
import {truthy} from '../../../../../utils/guards'
import Tooltip from '../../../../common/Tooltip/Tooltip'

import styles from './LinkHost.module.css'

export type LinkTarget = {
  to: string | null
  sakura: boolean
}

export type Props = {
  link?: LinkTarget | null
  isSakuraUI?: boolean
  children?: LinkProps['children']
  className?: string
  innerClassName?: string
  title?: ReactNode
  active?: boolean
  onClick?: LinkProps['onClick']
  icon?: string
  postIcon?: ReactNode
  counter?: number
  counterClassName?: string
  counterAttributes?: Record<string, string>
}

export default function LinkHost({
  link,
  isSakuraUI,
  children,
  icon,
  className,
  title,
  postIcon,
  counter,
  counterClassName,
  counterAttributes,
  ...props
}: Props) {
  const formatter = new Intl.NumberFormat('en', {notation: 'compact'})
  const content = (
    <>
      {icon && (
        <div className={styles.iconWrapper}>
          <SvgIcon className={styles.icon} icon={icon} />
          {truthy(counter) && (
            <span {...counterAttributes} className={classNames(styles.badge, counterClassName)}>
              {formatter.format(counter).toLowerCase()}
            </span>
          )}
          {postIcon}
        </div>
      )}
      <span>{children}</span>
    </>
  )

  const classes = classNames(styles.link, className, {
    [styles.active]: props.active,
    [styles.withCaption]: children,
  })
  const id = useId()
  return (
    <Tooltip
      id={id}
      delay={100}
      title={title}
      popupProps={{
        directions: [Directions.RIGHT_BOTTOM],
        /* eslint-disable @typescript-eslint/no-magic-numbers */
        top: children ? 8 : 4,
        offset: children ? 8 : 20,
        /* eslint-enable */
      }}
    >
      {isSakuraUI && link?.sakura && link?.to ? (
        <RouterLink
          aria-labelledby={id}
          data-selected={props.active}
          to={link?.to}
          {...props}
          passQueryParameters={false}
          className={classes}
        >
          {content}
        </RouterLink>
      ) : (
        <Link
          aria-labelledby={id}
          data-selected={props.active}
          href={link?.to ?? undefined}
          {...props}
          className={classes}
        >
          {content}
        </Link>
      )}
    </Tooltip>
  )
}
