import TeamcityLogo from '@jetbrains/logos/teamcity/teamcity.svg'
import Logo from '@jetbrains/ring-ui-built/components/header/logo'
import * as React from 'react'

import {isPipelinesEnabledInExclusiveMode} from '../../../../pages/PipelinesPages/utils/featureToggles'
import {LINKS} from '../../Header.consts'
import HeaderLinkHost from '../LinkHost/LinkHost.container'

import PipelinesLogo from './pipelinesLogo.svg'

import styles from './HomeLink.module.css'

function HomeLink() {
  const renderLogo = React.useMemo(
    () => (
      <Logo
        className={styles.logo}
        size={Logo.Size.Size40}
        glyph={isPipelinesEnabledInExclusiveMode() ? PipelinesLogo : TeamcityLogo}
        data-ignore-dark-theme-adapter
      />
    ),
    [],
  )
  const linkLogo = isPipelinesEnabledInExclusiveMode() ? LINKS.pipelines : LINKS.overview

  return (
    <div className={styles.container}>
      <HeaderLinkHost
        to={linkLogo}
        title={isPipelinesEnabledInExclusiveMode() ? 'TeamCity Pipelines' : 'TeamCity'}
      >
        {renderLogo}
      </HeaderLinkHost>
    </div>
  )
}

export default React.memo(HomeLink)
