import Link from '@jetbrains/ring-ui-built/components/link/link'
import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import classNames from 'classnames'

import useTimeSelector from '../../../../../hooks/useTimeSelector'
import Plugin from '../../../../common/Plugin/Plugin'
import {useCachedPlugins} from '../../../../common/Plugin/Plugin.hooks'
import {isPipelinesEnabledInExclusiveMode} from '../../../../pages/PipelinesPages/utils/featureToggles'

import {useFormattedVersionAndDetails} from './Footer.hooks'
import type {Props} from './Footer.types'

import styles from './Footer.module.css'

function Footer({licenseModeName, buildNumber}: Props) {
  const formattedVersionAndDetails = useFormattedVersionAndDetails()
  const hasFooterLinksExtensions = useCachedPlugins('FOOTER_LINKS' as PlaceId)
  const hasSakuraFooterRightExtensions = useCachedPlugins(PlaceId.SAKURA_FOOTER_RIGHT)
  const hasExtensions =
    hasFooterLinksExtensions.length > 0 || hasSakuraFooterRightExtensions.length > 0
  const currentYear = useTimeSelector(now => now.getFullYear())
  if (licenseModeName == null) {
    return null
  }

  return (
    <>
      <div>
        <Link
          href={
            isPipelinesEnabledInExclusiveMode()
              ? 'https://www.jetbrains.com/teamcity/pipelines/?fromServer'
              : 'https://www.jetbrains.com/teamcity/?fromServer'
          }
          target="_blank"
          rel="noreferrer"
        >{`TeamCity ${licenseModeName}`}</Link>{' '}
        {formattedVersionAndDetails}
      </div>
      {buildNumber && <div>{`Build ${buildNumber}`}</div>}
      <div className={styles.copyright}>{`Copyright © 2006–${currentYear} JetBrains s.r.o.`}</div>
      <div className={classNames({[styles.extensionsLinks]: hasExtensions})}>
        <Plugin placeId="FOOTER_LINKS" withoutLoader />
        <Plugin placeId={PlaceId.SAKURA_FOOTER_RIGHT} withoutLoader />
      </div>
    </>
  )
}

export default Footer
