import plur from 'plur'
import * as React from 'react'
import {useLocation} from 'react-router'

import {useFetchEffect} from '../../../../../hocs/withEffect'
import {getIsQueueSelected} from '../../../../../hooks/routes'
import {getIsSakuraUI} from '../../../../../selectors'
import {subscribeonStatisticsUpdates} from '../../../../../utils/subscriber'
import {headerQueueLinkHint} from '../../../../packages/Hints/HintItems/Hints.navigation'
import {useHint} from '../../../../packages/Hints/Hints.hooks'
import {LINKS} from '../../Header.consts'
import HeaderLinkHost from '../LinkHost/LinkHost.container'
import type {StatisticsUpdateData} from '../Links.types'
import {isActiveClassicUILink} from '../Links.utils'

import {useAppSelector} from 'src/hooks/react-redux'

function QueueLink() {
  useHint(headerQueueLinkHint)
  const isSakuraUI = useAppSelector(getIsSakuraUI)
  const [statistics, setStatistics] = React.useState<StatisticsUpdateData | null | undefined>(null)
  const location = useLocation()
  const queuePartSelected = getIsQueueSelected(location.pathname)
  const active = isSakuraUI ? queuePartSelected : isActiveClassicUILink('queue')
  const buildQueueSize = statistics?.buildQueueSize ?? 0
  useFetchEffect(
    () =>
      subscribeonStatisticsUpdates((data: StatisticsUpdateData | null | undefined) =>
        setStatistics(data),
      ),
    [],
  )
  return React.useMemo(
    () => (
      <HeaderLinkHost
        active={active}
        to={LINKS.buildQueue}
        title={`Queue: ${buildQueueSize} ${plur('build', buildQueueSize)}`}
        icon="hourglass-20px"
        counter={buildQueueSize}
        counterAttributes={{'data-hint-container-id': headerQueueLinkHint.id}}
      >
        {'Queue'}
      </HeaderLinkHost>
    ),
    [active, buildQueueSize],
  )
}

export default React.memo(QueueLink)
