import * as React from 'react'
import {useLocation} from 'react-router'

import {getIsChangesSelected} from '../../../../../hooks/routes'
import {getIsSakuraUI} from '../../../../../selectors'
import {LINKS} from '../../Header.consts'
import HeaderLinkHost from '../LinkHost/LinkHost.container'
import {isActiveClassicUILink} from '../Links.utils'

import {useAppSelector} from 'src/hooks/react-redux'

function ChangesLink() {
  const isSakuraUI = useAppSelector(getIsSakuraUI)
  const location = useLocation()
  const changesPartSelected = getIsChangesSelected(location.pathname)
  const active = isSakuraUI ? changesPartSelected : isActiveClassicUILink('changes')

  return (
    <HeaderLinkHost to={LINKS.changes} active={active} title={'Changes'} icon="changes-20px">
      {'Changes'}
    </HeaderLinkHost>
  )
}

export default React.memo(ChangesLink)
