import ArrowRightIcon from '@jetbrains/icons/arrow-right'
import giftIcon from '@jetbrains/icons/gift-20px'
import NewWindowIcon from '@jetbrains/icons/new-window'
import Security12pxIcon from '@jetbrains/icons/security-12px'
import timeIcon from '@jetbrains/icons/time-20px'
import Avatar, {Size} from '@jetbrains/ring-ui-built/components/avatar/avatar'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import {H3} from '@jetbrains/ring-ui-built/components/heading/heading'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import {ScrollHandlerContext} from '@jetbrains/ring-ui-built/components/island/adaptive-island-hoc'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import Tag from '@jetbrains/ring-ui-built/components/tag/tag'
import {Markdown} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {Fragment, Suspense, useMemo, useState} from 'react'

import {trackEvent} from '../../../../../statistics/statistics.lazy'
import {isPipelinesEnabledInExclusiveMode} from '../../../../pages/PipelinesPages/utils/featureToggles'
import {feedbackHref} from '../../HeaderTrayHelp/HeaderTrayHelp.consts'

import styles from './WhatsNewPopupContent.module.css'

export enum WhatsNewItemStatus {
  DRAFT = 'draft',
  PUBLISHED = 'published',
  ARCHIVED = 'archived',
}

export type Item = {
  id: number
  status: string
  title?: string | null
  description?: string | null
  link?: string | null
  call_to_action?: string | null
  tag?: string[] | null
  group?: string | null
}

type Props = {
  data: Item[]
  onShowFeedback?: () => void
}

function groupItems(data: Item[]) {
  const groups: string[] = []
  const index: Record<string, Item[]> = {}
  data.forEach(item => {
    const {group} = item
    if (!group) {
      return
    }
    if (!groups.includes(group)) {
      groups.push(group)
    }
    index[group] ??= []
    index[group].push(item)
  })
  return groups.map(group => ({group, items: index[group]}))
}

export default function WhatsNewPopupContent({data, onShowFeedback}: Props) {
  const groups = useMemo(() => groupItems(data), [data])
  const [scrolled, setScrolled] = useState(false)
  const trackShowFeedback = () =>
    trackEvent({groupId: 'whatsnew.events.group', name: 'leave.feedback.click'})
  return (
    <div className={styles.container}>
      <Header className={styles.header} border={scrolled}>
        {"What's new"}
      </Header>
      <ScrollHandlerContext.Provider value={({scrollTop}) => setScrolled(scrollTop > 0)}>
        <Content scrollableWrapperClassName={styles.content}>
          <Suspense>
            {groups.map(({group, items}, index) => {
              const isLatest = index === 0
              const isOldest = index === groups.length - 1
              return (
                <Fragment key={group}>
                  <div className={styles.releaseHeader}>
                    <Avatar
                      className={classNames({[styles.gift]: isLatest})}
                      size={Size.Size32}
                      info={
                        <Icon
                          className={styles.releaseIcon}
                          glyph={isLatest ? giftIcon : timeIcon}
                        />
                      }
                    />
                    <div>
                      <span className={styles.releaseSubtitle}>
                        {isLatest ? 'New updates! ✨' : 'Previous updates'}
                      </span>
                      <H3 className={styles.releaseTitle}>{group}</H3>
                    </div>
                    {isLatest &&
                      (isPipelinesEnabledInExclusiveMode() ? (
                        <Button
                          onClick={() => {
                            trackShowFeedback()
                            onShowFeedback?.()
                          }}
                          primary
                          className={styles.feedback}
                        >
                          {'Share feedback'}
                        </Button>
                      ) : (
                        <Button
                          onClick={trackShowFeedback}
                          href={feedbackHref}
                          target="_blank"
                          rel="noreferrer"
                          primary
                          className={styles.feedback}
                        >
                          {'Share feedback'}
                        </Button>
                      ))}
                  </div>
                  <div className={classNames(styles.timeline, {[styles.oldest]: isOldest})}>
                    {items.map(({tag, title, description, call_to_action, link}) => (
                      <div key={title} className={styles.event}>
                        <H3 className={styles.eventTitle}>
                          {tag?.map(tagName => {
                            const isSecurity = tagName === 'Security fix'
                            return (
                              <Tag
                                className={classNames(styles.tag, {[styles.security]: isSecurity})}
                                key={tagName}
                                render={({disabled, ...props}) => <span {...props} />}
                              >
                                {isSecurity && (
                                  <Icon glyph={Security12pxIcon} className={styles.securityIcon} />
                                )}
                                {tagName}
                              </Tag>
                            )
                          })}
                          {title}
                        </H3>
                        {description && (
                          <Markdown className={styles.description}>{description}</Markdown>
                        )}
                        {call_to_action && link && (
                          <Link
                            onClick={() =>
                              trackEvent({
                                groupId: 'whatsnew.events.group',
                                name: 'learn.more.click',
                              })
                            }
                            className={styles.callToAction}
                            target="_blank"
                            rel="noreferrer"
                            href={link}
                          >
                            {call_to_action}
                            <Icon glyph={ArrowRightIcon} />
                          </Link>
                        )}
                      </div>
                    ))}
                    {isOldest && (
                      <Link
                        target="_blank"
                        rel="noreferrer"
                        href={`https://blog.jetbrains.com/teamcity/tag/${isPipelinesEnabledInExclusiveMode() ? 'teamcity-pipelines-pulse' : 'release'}/`}
                      >
                        {'Read our blog for more updates'}
                        <Icon glyph={NewWindowIcon} className={styles.newWindowIcon} />
                      </Link>
                    )}
                  </div>
                </Fragment>
              )
            })}
          </Suspense>
        </Content>
      </ScrollHandlerContext.Provider>
    </div>
  )
}
