import RingLinks from '@jetbrains/ring-ui-built/components/header/links'
import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import * as React from 'react'

import Plugin from '../../../common/Plugin/Plugin'
import {
  isPipelinesAgentPageEnabled,
  isPipelinesEnabledInExclusiveMode,
} from '../../../pages/PipelinesPages/utils/featureToggles'

import AdministrationLink from './AdministrationLink/AdministrationLink'
import AgentsLink from './AgentsLink/AgentsLink'
import ChangesLink from './ChangesLink/ChangesLink'
import HomeLink from './HomeLink/HomeLink'
import PipelineAgentsLink from './PipelinesLink/AgentsLink'
import PipelinesLink from './PipelinesLink/PipelinesLink'
import ProjectsLink from './ProjectsLink/ProjectsLink'
import QueueLink from './QueueLink/QueueLink'

import styles from './Links.module.css'

type Props = {
  adminSpaceAvailable: boolean
}
function Links({adminSpaceAvailable}: Props) {
  return (
    <>
      <HomeLink />
      <RingLinks className={styles.links}>
        {isPipelinesEnabledInExclusiveMode() ? (
          <>
            <PipelinesLink />
            {isPipelinesAgentPageEnabled() && <PipelineAgentsLink />}
          </>
        ) : (
          <>
            <ProjectsLink />
            <ChangesLink />
            <AgentsLink />
            <QueueLink />
          </>
        )}
        {adminSpaceAvailable && <AdministrationLink />}
        <Plugin inline placeId={PlaceId.SAKURA_HEADER_NAVIGATION_AFTER} />
      </RingLinks>
    </>
  )
}

export default React.memo(Links)
