import Tray from '@jetbrains/ring-ui-built/components/header/tray'
import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import * as React from 'react'

import Plugin from '../../common/Plugin/Plugin'
import {
  isMuteInvestigateButtonEnabled,
  isPipelinesEnabledInExclusiveMode,
} from '../../pages/PipelinesPages/utils/featureToggles'

import HeaderTrayHelp from './HeaderTrayHelp/HeaderTrayHelp'
import HeaderUser from './HeaderUser/HeaderUser'
import InvestigationsCounter from './InvestigationsCounter/InvestigationsCounter'
import WhatsNew from './WhatsNew/WhatsNew'

import styles from './Header.module.css'

function HeaderTray() {
  return (
    <Tray className={styles.tray}>
      <Plugin placeId={PlaceId.SAKURA_HEADER_USERNAME_BEFORE} />
      {(!isPipelinesEnabledInExclusiveMode() || isMuteInvestigateButtonEnabled) && (
        <InvestigationsCounter />
      )}
      <WhatsNew />
      <HeaderTrayHelp />
      <Plugin placeId={PlaceId.SAKURA_HEADER_RIGHT} />
      <HeaderUser />
    </Tray>
  )
}

export default React.memo(HeaderTray)
