import Gift20pxIcon from '@jetbrains/icons/gift-20px'
import scrollPreventer from '@jetbrains/ring-ui-built/components/dialog/dialog__body-scroll-preventer'
import type {PopupAttrs} from '@jetbrains/ring-ui-built/components/popup/popup'
import Popup from '@jetbrains/ring-ui-built/components/popup/popup'
import {useEffect, useLayoutEffect} from 'react'

import data from '../../../../../downloads/whats-new/whats-new.json'
import pipelinesData from '../../../../../downloads/whats-new-pipelines/whats-new.json'
import {hideWhatsNew, openWhatsNew} from '../../../../actions'
import {useAppDispatch, useAppSelector} from '../../../../hooks/react-redux'
import {useSetUserProperty} from '../../../../hooks/useSetUserProperty'
import {useUserProperty} from '../../../../hooks/useUserProperty'
import {trackEvent} from '../../../../statistics/statistics.lazy'
import {UserProperties} from '../../../../utils/userProperties'
import {isPipelinesEnabledInExclusiveMode} from '../../../pages/PipelinesPages/utils/featureToggles'
import {feedbackHref} from '../HeaderTrayHelp/HeaderTrayHelp.consts'
import LinkHost from '../Links/LinkHost/LinkHost'

import type {Item} from './WhatsNewPopupContent/WhatsNewPopupContent'
import WhatsNewPopupContent, {WhatsNewItemStatus} from './WhatsNewPopupContent/WhatsNewPopupContent'

import styles from './WhatsNew.module.css'

let patchedData: Item[] = isPipelinesEnabledInExclusiveMode() ? pipelinesData : data
if (IS_STORYBOOK) {
  patchedData = [
    {
      id: 0,
      status: WhatsNewItemStatus.PUBLISHED,
      group: 'Pipelines new!',
      tag: ['Security fix'],
      title: 'Safeguarding  Exploitable Vulnerabilities',
      description:
        'Addresses critical vulnerabilities within the system, fortifying its defences against potential exploits.',
      call_to_action: 'Learn more',
      link: '/',
    },
  ]
} else {
  const assets = require.context('../../../../../downloads')
  patchedData = patchedData.map((item: Item) => ({
    ...item,
    description: assets
      .keys()
      .reduce((acc, key) => acc.replace(key, assets(key)), item.description ?? ''),
  }))
}

function WhatsNewPopup(props: PopupAttrs) {
  useLayoutEffect(() => {
    if (!props.hidden) {
      scrollPreventer.prevent()
      return () => scrollPreventer.reset()
    }
    return undefined
  }, [props.hidden])
  return <Popup {...props} />
}

export default function WhatsNew() {
  const isPopupOpen = useAppSelector(state => state.whatsNew.open)
  const lastSeenItem = useUserProperty(UserProperties.LAST_SEEN_WHATS_NEW_ITEM)
  const setUserProperty = useSetUserProperty()
  const dispatch = useAppDispatch()

  const lastItem = patchedData[0]?.group
  const highlight = lastSeenItem !== lastItem

  useEffect(() => {
    if (isPopupOpen && highlight && lastItem != null) {
      setUserProperty(UserProperties.LAST_SEEN_WHATS_NEW_ITEM, lastItem)
    }
  }, [highlight, isPopupOpen, lastItem, setUserProperty])

  if (patchedData.length === 0) {
    return null
  }

  const onClose = () => {
    dispatch(hideWhatsNew())
  }

  const onClick = () => {
    if (isPopupOpen) {
      onClose()
    } else {
      trackEvent({groupId: 'whatsnew.events.group', name: 'whatsnew.page.open'})
      dispatch(openWhatsNew())
    }
  }

  return (
    <>
      <LinkHost
        title="What's New"
        icon={Gift20pxIcon}
        postIcon={highlight && <span className={styles.dot} />}
        active={isPopupOpen}
        onClick={onClick}
      />
      <WhatsNewPopup
        dontCloseOnAnchorClick
        hidden={!isPopupOpen}
        directions={[Popup.PopupProps.Directions.RIGHT_TOP]}
        className={styles.popup}
        left={20}
        top={88}
        onCloseAttempt={onClose}
      >
        <WhatsNewPopupContent
          onShowFeedback={() => {
            window.open(feedbackHref, '_blank', 'noopener,noreferrer')
          }}
          data={patchedData}
        />
      </WhatsNewPopup>
    </>
  )
}
